package com.fasterxml.jackson.core.json;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonFactory;
import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.core.base.ParserBase;
import com.fasterxml.jackson.core.io.CharTypes;
import com.fasterxml.jackson.core.io.ContentReader;
import com.fasterxml.jackson.core.io.IOContext;
import com.fasterxml.jackson.core.io.JsonFactoryImpl;
import com.fasterxml.jackson.core.io.SerializableString;
import com.fasterxml.jackson.core.io.SerializableStringImpl;
import com.fasterxml.jackson.core.sym.CharsToNameCanonicalizer;
import com.fasterxml.jackson.core.util.*;
import java.io.*;
import java.io.IOException;
import java.io.StringReader;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for ReaderBasedJsonParser#nextFieldName
 */
public class ReaderBasedJsonParser_nextFieldName_TriageGen1Test {

    private JsonFactory _factory;

    @Before
    public void setUp() {
        _factory = new JsonFactoryImpl();
    }

    private ReaderBasedJsonParser createParser(String content) throws IOException {
        return (ReaderBasedJsonParser) _factory.createParser(new StringReader(content));
    }

    @Test
    public void testNextFieldName_MatchExact() throws IOException {
        String json = "{\"name\":\"value\"}";
        ReaderBasedJsonParser parser = createParser(json);

        parser.nextToken(); // Move to START_OBJECT

        SerializableString target = new SerializableStringImpl("name");
        boolean found = parser.nextFieldName(target);

        assertTrue("Should return true when field name matches", found);
        assertEquals(JsonToken.VALUE_STRING, parser.nextToken());
    }

    @Test
    public void testNextFieldName_NoMatch() throws IOException {
        String json = "{\"age\":30}";
        ReaderBasedJsonParser parser = createParser(json);

        parser.nextToken(); // START_OBJECT

        SerializableString target = new SerializableStringImpl("name");
        boolean found = parser.nextFieldName(target);

        assertFalse("Should return false when field name does not match", found);
    }

    @Test
    public void testNextFieldName_AlreadyAtFieldName() throws IOException {
        String json = "{\"name\":\"value\"}";
        ReaderBasedJsonParser parser = createParser(json);

        parser.nextToken(); // START_OBJECT
        parser.nextToken(); // FIELD_NAME "name"

        // Logic: if (_currToken == JsonToken.FIELD_NAME) return false
        SerializableString target = new SerializableStringImpl("name");
        boolean found = parser.nextFieldName(target);

        assertFalse("Should return false if current token is already a field name", found);
    }

    @Test
    public void testNextFieldName_EndArrayInObjectContext() throws IOException {
        // This tests the branch: if (i == INT_RBRACKET) and error reporting
        // We simulate a mismatch by having an array end where an object is expected
        String json = "{\"a\": [1, 2] ]"; // Note the extra ]
        ReaderBasedJsonParser parser = createParser(json);

        parser.nextToken(); // START_OBJECT
        parser.nextToken(); // FIELD_NAME "a"
        parser.nextToken(); // START_ARRAY
        parser.nextToken(); // 1
        parser.nextToken(); // 2
        parser.nextToken(); // END_ARRAY

        // Now we are at the extra ']'
        try {
            parser.nextFieldName(new SerializableStringImpl("any"));
            fail("Should have thrown MismatchedInputException");
        } catch (IOException e) {
            // Expected
        }
    }

    @Test
    public void testNextFieldName_EndObjectInObjectContext() throws IOException {
        String json = "{\"a\": 1} }";
        ReaderBasedJsonParser parser = createParser(json);

        parser.nextToken(); // START_OBJECT
        parser.nextToken(); // FIELD_NAME "a"
        parser.nextToken(); // 1
        parser.nextToken(); // END_OBJECT

        // Now at extra '}'
        try {
            parser.nextFieldName(new SerializableStringImpl("any"));
            fail("Should have thrown MismatchedInputException");
        } catch (IOException e) {
            // Expected
        }
    }

    @Test
    public void testNextFieldName_EndOfInput() throws IOException {
        String json = "{}";
        ReaderBasedJsonParser parser = createParser(json);

        parser.nextToken(); // START_OBJECT
        parser.nextToken(); // END_OBJECT

        // Now at EOF
        boolean found = parser.nextFieldName(new SerializableStringImpl("any"));
        assertFalse("Should return false at EOF", found);
    }

    @Test
    public void testNextFieldName_NotInObjectContext() throws IOException {
        // Testing: if (!_parsingContext.inObject()) { _nextTokenNotInObject(i); return false; }
        String json = "[1, 2, 3]";
        ReaderBasedJsonParser parser = createParser(json);

        parser.nextToken(); // START_ARRAY

        try {
            parser.nextFieldName(new SerializableStringImpl("any"));
            fail("Should throw exception because nextFieldName called inside array");
        } catch (IOException e) {
            // Expected
        }
    }

    @Test
    public void testNextFieldName_WithComma() throws IOException {
        String json = "{\"a\":1, \"b\":2}";
        ReaderBasedJsonParser parser = createParser(json);

        parser.nextToken(); // START_OBJECT
        parser.nextFieldName(new SerializableStringImpl("a"));
        parser.nextToken(); // 1

        // This should skip the comma and find "b"
        boolean found = parser.nextFieldName(new SerializableStringImpl("b"));
        assertTrue("Should skip comma and find next field name", found);
    }

    @Test
    public void testNextFieldName_IncompleteToken() throws IOException {
        // Tests the _tokenIncomplete branch
        // This is harder to trigger with standard string input, 
        // but we can simulate via a parser that expects more data
        String json = "{\"a\":"; 
        ReaderBasedJsonParser parser = createParser(json);

        parser.nextToken(); // START_OBJECT
        parser.nextFieldName(new SerializableStringImpl("a"));

        // After "a":, the parser is in an incomplete state for the value
        // We can't easily force _tokenIncomplete via StringReader, 
        // but we verify the logic flow works for standard parsing.
        assertNotNull(parser.getCurrentLocation());
    }

    @Test
    public void testNextFieldName_FastSkipColonPath() throws IOException {
        // Tests the branch: if ((_inputPtr + len + 4) < _inputEnd)
        // This triggers the optimized path for matching the name and skipping the colon
        String json = "{\"key\":\"value\"}";
        ReaderBasedJsonParser parser = createParser(json);

        parser.nextToken(); // START_OBJECT

        // Use a name that allows the "len + 4" buffer check to pass
        SerializableString sstr = new SerializableStringImpl("key");
        boolean found = parser.nextFieldName(sstr);

        assertTrue(found);
        assertEquals(JsonToken.VALUE_STRING, parser.nextToken());
    }
}
